Signed-off-by: John Johansen <john.johansen@canonical.com>

Here is the root cause:
In the `d_namespace_path` function, when appending a '/' to directory paths that are not root, the code wrote the slash at `buf[aa_g_path_max - 2]` but did not null-terminate at `buf[aa_g_path_max - 1]`, leaving the buffer unterminated. This caused subsequent string operations (e.g., `aa_dfa_match`) to read past the allocated buffer, resulting in a KASAN slab-out-of-bounds error.

Here is the patch:
  */
 static int d_namespace_path(const struct path *path, char *buf, char **name,
 			    int flags, const char *disconnected)
 {
 	char *res;
 	int error = 0;
 	int connected = 1;
 	int isdir = (flags & PATH_IS_DIR) ? 1 : 0;
 	int buflen = aa_g_path_max - isdir;

 	if (path->mnt->mnt_flags & MNT_INTERNAL) {
 		/* it's not mounted anywhere */
 		res = dentry_path(path->dentry, buf, buflen);
 		*name = res;
 		if (IS_ERR(res)) {
 			*name = buf;
 			return PTR_ERR(res);
 		}
 		if (path->dentry->d_sb->s_magic == PROC_SUPER_MAGIC &&
 		    strncmp(*name, "/sys/", 5) == 0) {
 			/* TODO: convert over to using a per namespace
 			 * control instead of hard coded /proc
 			 */
 			error = prepend(name, *name - buf, "/proc", 5);
 			goto out;
 		} else
 			error = disconnect(path, buf, name, flags,
 					   disconnected);
 		goto out;
 	}

 	/* resolve paths relative to chroot?*/
 	if (flags & PATH_CHROOT_REL) {
 		struct path root;
 		get_fs_root(current->fs, &root);
 		res = __d_path(path, &root, buf, buflen);
 		path_put(&root);
 	} else {
 		res = d_absolute_path(path, buf, buflen);
 		if (!our_mnt(path->mnt))
 			connected = 0;
 	}

 	/* handle error conditions - and still allow a partial path to
 	 * be returned.
 	 */
 	if (IS_ERR_OR_NULL(res)) {
 		if (PTR_ERR(res) == -ENAMETOOLONG) {
 			error = -ENAMETOOLONG;
 			*name = buf;
 			goto out;
 		}
 		connected = 0;
 		res = dentry_path_raw(path->dentry, buf, buflen);
 		if (IS_ERR(res)) {
 			error = PTR_ERR(res);
 			*name = buf;
 			goto out;
 		}
 	} else if (!our_mnt(path->mnt))
 		connected = 0;

 	*name = res;

 	if (!connected)
 		error = disconnect(path, buf, name, flags, disconnected);

 	/* Handle two cases:
 	 * 1. A deleted dentry && profile is not allowing mediation of deleted
 	 * 2. On some filesystems, newly allocated dentries appear to the
 	 *    security_path hooks as a deleted dentry except without an inode
 	 *    allocated.
 	 */
 	if (d_unlinked(path->dentry) && d_is_positive(path->dentry) &&
 	    !(flags & (PATH_MEDIATE_DELETED | PATH_DELEGATE_DELETED))) {
 			error = -ENOENT;
 			goto out;
 	}

 out:
-	/* Append "/" to directory paths, except for root "/" which
-	 * already ends in a slash.
+	/* Append "/" to directory paths and reterminate string, except for
+	 * root "/" which already ends in a slash.
 	 */
 	if (!error && isdir) {
 		bool is_root = (*name)[0] == '/' && (*name)[1] == '\0';

-		if (!is_root)
+		if (!is_root) {
 			buf[aa_g_path_max - 2] = '/';
+			buf[aa_g_path_max - 1] = '\0';
+		}
 	}

 	return error;
 }



